// Leest de multipart-upload van /bespreking: één audiobestand + wat losse
// tekstvelden. De webapp levert 16 kHz mono WAV aan (client-side geconverteerd
// via de Web Audio API), zodat er nergens in de keten ffmpeg nodig is —
// whisper.cpp eet precies dit formaat.
//
// In plaats van audio mag ook een kant-en-klaar `transcript`-veld worden
// meegestuurd. Dan wordt de Whisper-stap overgeslagen. Bedoeld om de
// samenvatting te beproeven met een uitgeschreven script: zo zit er geen
// transcriptieruis tussen en test je alleen wat het model ervan maakt.
const item = $input.first();
const binary = (item && item.binary) || {};
const body = (item && item.json && item.json.body) || item.json || {};

function veld(naam, standaard) {
  const v = body[naam];
  return v === undefined || v === null || v === '' ? standaard : String(v);
}

const audioKey = Object.keys(binary).find((k) => {
  const mime = String(binary[k]?.mimeType || '').toLowerCase();
  const name = String(binary[k]?.fileName || '').toLowerCase();
  return mime.startsWith('audio/') || /\.(wav|mp3|m4a|webm|ogg|flac)$/.test(name);
});

// Een transcript kan als tekstveld of als .txt-bijlage binnenkomen.
let transcriptTekst = veld('transcript', '');
if (!transcriptTekst) {
  const txtKey = Object.keys(binary).find((k) =>
    /\.txt$/i.test(String(binary[k]?.fileName || ''))
  );
  if (txtKey) {
    const buffer = await this.helpers.getBinaryDataBuffer(0, txtKey);
    transcriptTekst = buffer.toString('utf8');
  }
}
transcriptTekst = transcriptTekst.trim();

if (!audioKey && !transcriptTekst) {
  throw new Error(
    'Webhook ontving geen audiobestand en geen transcript. Stuur een WAV/MP3/M4A mee ' +
      'als multipart/form-data, of een veld `transcript` met uitgeschreven tekst.'
  );
}

// Referentie bepaalt de bestandsnaam. Dossiernummer als de gebruiker het invult,
// anders een tijdstempel — nooit de (mogelijk persoonsgebonden) titel.
const nu = new Date();
const stempel =
  nu.getFullYear() +
  String(nu.getMonth() + 1).padStart(2, '0') +
  String(nu.getDate()).padStart(2, '0') +
  '_' +
  String(nu.getHours()).padStart(2, '0') +
  String(nu.getMinutes()).padStart(2, '0') +
  String(nu.getSeconds()).padStart(2, '0');

const dossier = veld('dossier', '');
const referentie = (dossier || stempel).replace(/[^0-9A-Za-z_.-]/g, '_');

// Jobbestand aanmaken. De webhook antwoordt hierna meteen met dit job_id en de
// workflow loopt daarachter door; de webapp pollt de status. Zo hoeft er geen
// HTTP-verbinding een uur open te blijven voor een lange bespreking.
const fs = require('fs');
const JOB_DIR = '/data/shared/jobs';
const jobId = `${stempel}_${String($execution.id || Math.random().toString(36).slice(2))}`
  .replace(/[^0-9A-Za-z_-]/g, '_');

// Soort bespreking bepalen: expliciet meegegeven, anders afgeleid uit het
// onderwerp aan de hand van `herken_op` in de sjablonen. Let op de volgorde van
// herkennen: "testament" zit ook in "levenstestament", dus het lángste passende
// trefwoord wint — anders belandt een levenstestament onder het testamentsjabloon.
const SJABLOON_DIR = '/data/shared/templates/besprekingen';
let soort = veld('soort', '').trim().toLowerCase();

if (!soort || soort === 'auto') {
  const zoektekst = `${veld('onderwerp', '')} ${veld('dossier', '')}`.toLowerCase();
  let beste = { soort: '', lengte: 0 };
  try {
    for (const naam of fs.readdirSync(SJABLOON_DIR)) {
      if (!naam.endsWith('.json')) continue;
      const sj = JSON.parse(fs.readFileSync(`${SJABLOON_DIR}/${naam}`, 'utf8'));
      for (const woord of sj.herken_op || []) {
        const w = String(woord).toLowerCase();
        if (zoektekst.includes(w) && w.length > beste.lengte) {
          beste = { soort: sj.soort, lengte: w.length };
        }
      }
    }
  } catch (_) {
    // Geen sjabloonmap of onleesbaar bestand: dan gewoon een vrij verslag.
  }
  soort = beste.soort || 'algemeen';
}

fs.mkdirSync(JOB_DIR, { recursive: true });

// Oude jobbestanden opruimen. Ze bevatten het volledige transcript van een
// cliëntbespreking, dus ze horen niet langer te blijven staan dan nodig is om
// het resultaat op te halen. Een dag is ruim; het verslag zelf staat als .docx
// in shared/output.
const BEWAARTERMIJN_MS = 24 * 60 * 60 * 1000;
try {
  for (const naam of fs.readdirSync(JOB_DIR)) {
    if (!naam.endsWith('.json')) continue;
    const pad = `${JOB_DIR}/${naam}`;
    if (Date.now() - fs.statSync(pad).mtimeMs > BEWAARTERMIJN_MS) fs.unlinkSync(pad);
  }
} catch (_) {
  // Opruimen is best-effort; een nieuwe bespreking mag er niet op stuklopen.
}

fs.writeFileSync(
  `${JOB_DIR}/${jobId}.json`,
  JSON.stringify({
    job_id: jobId,
    soort,
    // Met een meegestuurd transcript begint de job meteen bij het samenvatten.
    status: audioKey ? 'transcriberen' : 'samenvatten',
    fase: audioKey ? 1 : 2,
    referentie,
    dossier,
    datum: veld('datum', nu.toLocaleDateString('nl-NL')),
    duur_seconden: Number(veld('duur_seconden', '0')) || 0,
    blok_aantal: null,
    resultaat: null,
    fout: null,
    gestart_op: nu.toISOString(),
    bijgewerkt_op: nu.toISOString(),
  }),
  'utf8'
);

// Initial prompt voor Whisper: alleen het onderwerp en de deelnemers.
//
// Bewust géén lijst met vaktermen meer. Gemeten op een echte bespreking van 55
// minuten kostte zo'n lijst van 29 termen 900 woorden inhoud (5.620 tegen 6.545)
// en verdubbelde hij de hallucinatielussen; met large-v3 stortte de transcriptie
// zelfs volledig in (795 woorden). Winst was alleen een betere spelling van
// "langslevende" — te weinig voor die prijs. Een korte prompt met namen houdt
// het naam-voordeel zonder die schade.
//
// Kort houden: Whisper kapt de initial prompt af rond de 224 tokens, en een
// lange, lijstachtige prompt zonder natuurlijke zinsbouw lokt herhaling uit.
//
// Let op: sinds de whisper-server met --max-context 0 draait (zie
// start-whisper-server.sh) gebruikt hij deze prompt niet meer. Hij blijft
// meegaan voor wie de server anders start.
//
// Gewone zinnen, geen "Label: waarde". Met "Aanwezig: …" in de prompt nam
// Whisper dat woord over als sprekerlabel en zette het vóór elke beurt — 101
// keer in een bespreking van 35 minuten.
const zonderPunt = (t) => String(t).trim().replace(/[.\s]+$/, '');
const whisperDelen = ['Notariële bespreking.'];
if (veld('onderwerp', '')) whisperDelen.push(`${zonderPunt(veld('onderwerp', ''))}.`);

// Wie is behandelaar en wie cliënt? De webapp stuurt de behandelaar apart mee.
// Ontbreekt dat veld (ouder formulier, script), dan geldt een deelnemer met
// "mr." of een functie in de naam als behandelaar. Het onderscheid gaat de
// samenvatprompts in: zonder wist het model niet over wie het verslag ging en
// schreef het de ziekte en de broer van de cliënt aan de notaris toe.
const FUNCTIE = /^(mr\.?|notaris|kandidaat[- ]notaris|notarisklerk)\s/i;
const splitsNamen = (t) =>
  String(t || '').split(/[,;\n]/).map((n) => n.trim()).filter(Boolean);
let behandelaars = splitsNamen(veld('behandelaar', ''));
let clienten = splitsNamen(veld('deelnemers', ''));
if (!behandelaars.length) {
  behandelaars = clienten.filter((n) => FUNCTIE.test(n));
  clienten = clienten.filter((n) => !FUNCTIE.test(n));
} else {
  const al = new Set(behandelaars.map((n) => n.toLowerCase()));
  clienten = clienten.filter((n) => !al.has(n.toLowerCase()));
}
const aanwezigen = [...behandelaars, ...clienten];
if (aanwezigen.length) whisperDelen.push(`Gesprek tussen ${aanwezigen.join(', ')}.`);

return [{
  json: {
    jobId,
    soort,
    whisperPrompt: whisperDelen.join(' '),
    audioField: audioKey || '',
    heeftAudio: !!audioKey,
    transcriptTekst,
    filename: binary[audioKey]?.fileName || (transcriptTekst ? 'transcript.txt' : 'opname.wav'),
    dossier,
    onderwerp: veld('onderwerp', ''),
    deelnemers_invoer: aanwezigen.join(', '),
    behandelaars,
    clienten,
    // Vrije context van de behandelaar: wat je niet uit de opname kunt horen
    // maar wel het gesprek duidt ("mevrouw stottert", "de heer voerde vrijwel
    // het hele gesprek"). Gaat bewust NIET naar Whisper: een langere initial
    // prompt kostte gemeten inhoud. Wel naar de samenvatstappen als achtergrond,
    // en letterlijk in het verslag — het is een waarneming van de behandelaar en
    // hoort onveranderd in het dossier.
    context: veld('context', '').trim(),
    datum: veld('datum', nu.toLocaleDateString('nl-NL')),
    duur_seconden: Number(veld('duur_seconden', '0')) || 0,
    referentie,
    ontvangenOp: nu.toISOString(),
  },
  binary: item.binary,
}];

// Er is een uitgeschreven transcript meegestuurd in plaats van audio; de
// Whisper-stap wordt dan overgeslagen. We leveren hier dezelfde vorm aan als
// whisper-server ({ text }), zodat Extract Transcript geen weet hoeft te hebben
// van welke van de twee routes het is.
return [{ json: { text: String($json.transcriptTekst || '') } }];

// Haalt het transcript uit de whisper-respons en knipt het in blokken.
//
// Waarom knippen: de Ollama-node draait met numCtx 8192, waarvan na aftrek van
// de output ~6000 tokens voor de prompt overblijven. 9000 tekens transcript is
// ruwweg 2300 tokens en laat ruim marge voor instructies. Eén blok komt overeen
// met ongeveer een kwartier spreektijd. Is de bespreking langer, dan vat de
// workflow eerst elk blok apart samen (map) en bouwt daarna het verslag uit die
// deelsamenvattingen (reduce) — zo verdwijnt het tweede uur niet stilzwijgend
// uit het verslag.
const BLOK_TEKENS = 9000;

const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Prepare Audio').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (handmatig opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

const resp = $json || {};

// De whisper-node draait met onError=continueRegularOutput, zodat een niet-
// draaiende server hier netjes in het jobbestand belandt in plaats van de
// workflow stil te laten sneuvelen — de webapp pollt en zou anders blijven
// wachten op een antwoord dat nooit komt.
if (resp.error) {
  const melding =
    'Whisper antwoordde niet. Draait de server? Start met ./shared/whisper/start-whisper-server.sh';
  werkJobBij({ status: 'fout', fout: melding });
  throw new Error(melding);
}

// whisper-server geeft {"text": "..."}; bij response_format=verbose_json zit de
// tekst in dezelfde sleutel, met segments ernaast.
let transcript = String(resp.text || resp.transcript || '').trim();
if (!transcript && Array.isArray(resp.segments)) {
  transcript = resp.segments.map((s) => s.text || '').join(' ').trim();
}
if (!transcript) {
  const melding = 'Whisper gaf een leeg transcript terug. Bevat de opname spraak?';
  werkJobBij({ status: 'fout', fout: melding });
  throw new Error(melding);
}

// --- Opschonen ---------------------------------------------------------------
// 1. Sprekerlabels. Met "Aanwezig: …" in de initial prompt nam Whisper dat woord
//    over als label vóór elke beurt (101 keer in 35 minuten). De prompt bevat
//    geen labels meer, maar het patroon is te schadelijk om op te vertrouwen:
//    komt zo'n label drie keer of vaker voor, dan gaat het eruit.
const ruwTranscript = transcript;
const labelsVerwijderd = (transcript.match(/\b(Aanwezig|Onderwerp|Deelnemers|Spreker(?: \d+)?):\s*/g) || []).length;
if (labelsVerwijderd >= 3) {
  transcript = transcript.replace(/\b(Aanwezig|Onderwerp|Deelnemers|Spreker(?: \d+)?):\s*/g, '');
}

// 2. Herhalingslussen. Whisper loopt op stukken met zachte of overlappende
//    spraak vast en schrijft dan dezelfde zin vele malen ("Dat is de verkoop van
//    de zorgzaken" × 9). Dat is geen nadruk van de spreker maar verloren tekst.
//    Drie of meer gelijke zinnen op rij worden er één; bij een inhoudelijke zin
//    blijft een markering staan, zodat de lezer van de bijlage ziet dat daar iets
//    ontbreekt. Een rij "Ja. Ja. Ja." krimpt zonder markering: dat is ruis.
function ontdubbel(tekst) {
  const zinnen = tekst.match(/[^.!?…]*[.!?…]+["')\]]*\s*|[^.!?…]+$/g) || [tekst];
  const sleutel = (z) => z.toLowerCase().replace(/[^a-z0-9À-ÿ]+/g, '');
  const uit = [];
  let lussen = 0;
  let geschrapt = 0;
  for (let i = 0; i < zinnen.length; ) {
    const k = sleutel(zinnen[i]);
    let j = i + 1;
    while (k && j < zinnen.length && sleutel(zinnen[j]) === k) j += 1;
    const n = j - i;
    if (n >= 3) {
      uit.push(zinnen[i].trimEnd());
      if (k.length > 12) {
        uit.push(` [${n}× herhaald]`);
        lussen += 1;
      }
      uit.push(' ');
      geschrapt += n - 1;
    } else {
      uit.push(...zinnen.slice(i, j));
    }
    i = j;
  }
  return { tekst: uit.join('').replace(/[ \t]{2,}/g, ' ').trim(), lussen, geschrapt };
}

const ontdubbeld = ontdubbel(transcript);
transcript = ontdubbeld.tekst;

// Knip op zinseinde in plaats van middenin een woord: een blok dat halverwege
// een bedrag of naam afbreekt levert onbruikbare deelsamenvattingen op.
function knip(tekst, max) {
  const blokken = [];
  let rest = tekst;
  while (rest.length > max) {
    const venster = rest.slice(0, max);
    let snij = Math.max(
      venster.lastIndexOf('. '),
      venster.lastIndexOf('? '),
      venster.lastIndexOf('! ')
    );
    if (snij < max * 0.5) snij = venster.lastIndexOf(' ');
    if (snij <= 0) snij = max;
    blokken.push(rest.slice(0, snij + 1).trim());
    rest = rest.slice(snij + 1).trim();
  }
  if (rest) blokken.push(rest);
  return blokken;
}

const blokken = knip(transcript, BLOK_TEKENS);

werkJobBij({ status: 'samenvatten', fase: 2, blok_aantal: blokken.length });

return [{
  json: {
    transcript,
    transcript_tekens: transcript.length,
    // Voor de waarschuwing in het resultaat (Build Bespreking Response).
    transcript_lussen: ontdubbeld.lussen,
    transcript_zinnen_geschrapt: ontdubbeld.geschrapt,
    transcript_labels_verwijderd: labelsVerwijderd >= 3 ? labelsVerwijderd : 0,
    transcript_tekens_ruw: ruwTranscript.length,
    blokken,
    blok_aantal: blokken.length,
    meerdere_blokken: blokken.length > 1,
  },
}];

// Zet elk transcript-blok om in een eigen item, zodat de chain-node er één
// LLM-aanroep per blok van maakt (de map-stap).
//
// Is er een sjabloon (testament, levenstestament), dan vat elk blok meteen samen
// ÓNDER de vaste kopjes. Dat is bewust: eerder vatte de map-stap elk blok vrij
// samen en moest de verslag-ronde de flarden daarna alsnog onder 17 juridische
// kopjes sorteren. Dat lukte niet — bij een echte bespreking van 46 minuten bleven
// 14 van de 17 kopjes leeg en belandde "60% naar Kline Clowns" onder "Overige"
// in plaats van onder "Legaten". De details die je nodig hebt om zoiets te
// herkennen, waren in de samenvatstap al weggevallen.
const fs = require('fs');

const bron = $json || {};
const blokken = Array.isArray(bron.blokken) ? bron.blokken : [];
const meta = $('Prepare Audio').first()?.json || {};

// Achtergrond van de behandelaar. Staat vóór het transcriptdeel zodat het model
// weet hoe het de tekst moet lezen — bij een spreker die stottert of hakkelt is
// een herhaling geen nadruk maar ruis. Nadrukkelijk als achtergrond aangemerkt,
// anders belandt de waarneming zelf als besproken punt in het verslag.
const waarneming = String(meta.context || '').trim();
const waarnemingBlok = waarneming
  ? `ACHTERGROND VAN DE BEHANDELAAR (over hoe het gesprek verliep, niet over de inhoud — schrijf dit nooit over als punt)
${waarneming}

`
  : '';

// Wie is wie. Het transcript vermeldt geen sprekers, dus zonder deze regels weet
// het model niet over wie het verslag gaat: bij een levenstestament schreef het
// de ziekte en de broer van de cliënt aan de notaris toe. Staat ook zonder namen
// in de prompt — de rolverdeling zelf is het punt.
function rollenBlok(meta) {
  const b = (meta.behandelaars || []).join(', ');
  const c = (meta.clienten || []).join(', ');
  return `ROLLEN
- Behandelaar${b ? ` (${b})` : ''}: medewerker van het notariskantoor. Stelt de vragen en legt de wet uit.
- Cliënten${c ? ` (${c})` : ''}: over hén gaat het verslag — hun familie, gezondheid, vermogen, wensen en keuzes.
- Het transcript zegt niet wie er spreekt. Wie uitlegt en vragen stelt is de behandelaar; wie over het eigen leven vertelt is een cliënt.
- Schrijf nooit iets toe aan de behandelaar of "de notaris" dat over het leven van een mens gaat (ziekte, broer, partner, testament, wensen). Dat gaat altijd over een cliënt; schrijf dan "cliënt" of "cliënten".
- Algemene uitleg van de behandelaar over de wet of over wat er mogelijk is, is geen keuze van de cliënten. Noteer wat voor déze cliënten geldt of wat zij willen.

`;
}
const rollen = rollenBlok(meta);

let sjabloon = null;
try {
  const soort = String(meta.soort || '').replace(/[^a-z]/gi, '').toLowerCase();
  if (soort && soort !== 'algemeen') {
    sjabloon = JSON.parse(
      fs.readFileSync(`/data/shared/templates/besprekingen/${soort}.json`, 'utf8')
    );
  }
} catch (_) {
  // Geen sjabloon: dan de vrije samenvatting hieronder.
}

// Deterministische voorselectie: welke kopjes komen in dít blok waarschijnlijk
// aan de orde? Puur op trefwoorden uit het sjabloon, zonder model. Reden: het
// model zette de legaten aan de stichtingen onder "Uitsluitingsclausule" — een
// kopje dat leeg had moeten blijven — terwijl "stichting" letterlijk in de tekst
// staat. Zo'n aanwijzing kost niets en stuurt precies daar bij.
function raakKopjes(blok) {
  const tekst = blok.toLowerCase();
  return sjabloon.secties
    .filter((sec) => (sec.trefwoorden || []).some((w) => tekst.includes(String(w).toLowerCase())))
    .map((sec) => sec.kop);
}

// De lijsten "afspraken" en "namen" staan leeg in het schema en worden in de
// regels uitgelegd. Een omschrijving ín het schema schrijft dit model terug als
// inhoud, en een open omschrijving ("wie gaat wat doen") zonder maximum liet het
// alle keuzes van de cliënten als afspraak opsommen, eindigend in dezelfde zin
// tot de uitvoer vol was — waarna de JSON ongeldig is en het héle deel wegvalt.
function promptMetSjabloon(blok, i, totaal) {
  // De volledige aanwijzing per kopje, niet een afkorting: met korte hints zakte
  // het aantal gevulde kopjes van 11 naar 8 en belandden de legaten weer onder
  // "Overige". De prompt wordt er groot van (~12.600 tekens), maar sinds de
  // blokken één voor één draaien is dat geen probleem meer.
  const raak = raakKopjes(blok);
  const laatsteKop = sjabloon.secties[sjabloon.secties.length - 1].kop;
  const koppen = sjabloon.secties
    .map((sec) => `- ${sec.kop}: ${sec.aanwijzing}`)
    .join('\n');
  const leegSchema = sjabloon.secties
    .map((sec) => `    "${sec.kop}": []`)
    .join(',\n');

  return `Hieronder staat deel ${i + 1} van ${totaal} van een automatisch transcript van een notariële bespreking (${sjabloon.naam}).

Orden wat er in DIT deel is besproken onder de vaste kopjes hieronder. Gebruik uitsluitend wat er staat; verzin niets.

${rollen}${waarnemingBlok}KOPJES (de tekst achter de dubbele punt is een aanwijzing voor jou — schrijf die nooit over als inhoud)
${koppen}

${raak.length ? `LET OP — in dit deel vallen woorden die horen bij: ${raak.join(', ')}. Kijk of die kopjes hier gevuld moeten worden. Het omgekeerde geldt ook: een kopje dat hier niet tussen staat, is hier waarschijnlijk niet aan de orde.\n` : ''}
REGELS
- Schrijf wat er over het onderwerp is gezegd, met de inhoud erbij.
- In één deel komen maar een paar kopjes aan bod. Vul een kopje alleen met wat de cliënten erover vertelden of kozen; alle andere kopjes blijven een lege lijst. Verzin geen punt om een kopje te vullen.
- Schrijf de uitkomst op, niet dát erover is gesproken. Niet "Er wordt besproken dat…" of "Er wordt gekeken naar…", maar wat er is gezegd of gekozen.
- Zet hetzelfde punt nooit onder twee kopjes.
- Hooguit zes punten per kopje, één korte zin per punt.
- Noem concrete namen, bedragen en percentages als die vallen; juist die maken het punt bruikbaar.
- Staat er "[9× herhaald]" of iets dergelijks, dan liep de transcriptie daar vast en ontbreekt er tekst. Maak daar geen punt van.
- Een punt is een hele zin die zegt wat er is verteld of besloten. Een los trefwoord of een rijtje onderwerpen is geen punt.
- "afspraken": alleen wat iemand ná dit gesprek nog gaat doen. Wat de cliënten kiezen of willen hoort onder een kopje. Hooguit vijf, geen enkele twee keer; niets afgesproken is een lege lijst.
- "namen": de namen van personen die in dit deel vallen.
- Twijfel je onder welk kopje iets hoort, kies dan het meest specifieke kopje dat past. Gebruik "${laatsteKop}" alleen als het echt nergens onder valt.

Geef alleen geldige JSON terug:
{
  "secties": {
${leegSchema}
  },
  "afspraken": [],
  "namen": []
}

TRANSCRIPT-DEEL
${blok}`;
}

function promptVrij(blok, i, totaal) {
  return `Hieronder staat deel ${i + 1} van ${totaal} van een automatisch transcript van een notariële bespreking.

Vat dit deel samen in korte, feitelijke punten. Gebruik uitsluitend wat er staat; verzin niets. Laat een lijst alleen leeg als er echt niets over gezegd is.

${rollen}${waarnemingBlok}Houd het compact: hooguit acht punten per lijst en één korte zin per punt. Een te lang antwoord wordt afgekapt en is dan onbruikbaar.

Geef alleen geldige JSON terug:
{
  "besproken": ["korte punten over wat er in dit deel is besproken"],
  "afspraken": ["afspraken die in dit deel zijn gemaakt"],
  "namen": ["namen of rollen die in dit deel vallen"]
}

TRANSCRIPT-DEEL
${blok}`;
}

return blokken.map((blok, i) => ({
  json: {
    blokIndex: i + 1,
    blokTotaal: blokken.length,
    sjabloonSoort: sjabloon ? sjabloon.soort : null,
    chatInput: sjabloon
      ? promptMetSjabloon(blok, i, blokken.length)
      : promptVrij(blok, i, blokken.length),
  },
}));

// Werkt het jobbestand bij na elk samengevat blok en geeft het item door aan de
// lus. Zonder dit ligt de status stil zolang de blokken draaien.
const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Prepare Audio').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (handmatig opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

const totaal = Number($('Split Blokken').first()?.json?.blokTotaal || 0);
const gedaan = $runIndex + 1;

werkJobBij({
  status: 'samenvatten',
  fase: 2,
  blok_voortgang: totaal ? `${Math.min(gedaan, totaal)}/${totaal}` : String(gedaan),
});

return $input.all();

// Reduce-stap: voegt de deelsamenvattingen samen tot één compacte basistekst
// waar de verslag-prompt mee verder kan.
// De modelstappen roepen Ollama rechtstreeks aan (HTTP Request in plaats van de
// Ollama-node): alleen zo is `think: false` mee te geven, en zonder dat schrijft
// qwen3.5 zijn denkproces als antwoord. Het antwoord staat dan als tekst in
// message.content. Bijvangst: is die tekst afgekapt (uitvoerlimiet, of het model
// dat in herhaling valt), dan is er nu iets te redden. Via de Ollama-node viel bij
// ongeldige JSON het hele deel weg.
function repareerJson(tekst) {
  const s = String(tekst);
  const stapel = [];
  let inTekst = false;
  let ontsnapt = false;
  let veilig = null;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (inTekst) {
      if (ontsnapt) ontsnapt = false;
      else if (c === '\\') ontsnapt = true;
      else if (c === '"') {
        inTekst = false;
        // Een afgeronde tekst ín een lijst is een heel punt: daar mag de knip.
        if (stapel[stapel.length - 1] === '[') veilig = { tot: i + 1, open: stapel.slice() };
      }
      continue;
    }
    if (c === '"') inTekst = true;
    else if (c === '{' || c === '[') stapel.push(c);
    else if (c === '}' || c === ']') {
      stapel.pop();
      veilig = { tot: i + 1, open: stapel.slice() };
    }
  }
  if (!veilig) return null;
  const sluit = veilig.open.reverse().map((h) => (h === '[' ? ']' : '}')).join('');
  try {
    return JSON.parse(s.slice(0, veilig.tot) + sluit);
  } catch (_) {
    return null;
  }
}

// Geeft undefined als het item niet van een rechtstreekse aanroep komt.
function leesOllama(j) {
  if (typeof j?.message?.content !== 'string') return undefined;
  const tekst = j.message.content.replace(/```(?:json)?/gi, '').trim();
  try {
    return JSON.parse(tekst);
  } catch (_) {
    const gered = repareerJson(tekst);
    if (gered && typeof gered === 'object') gered._afgekapt = true;
    return gered;
  }
}

function haalObject(j) {
  if (!j || typeof j !== 'object') return null;
  const direct = leesOllama(j);
  if (direct !== undefined) return direct;
  for (const k of ['text', 'output', 'answer', 'response']) {
    if (typeof j[k] === 'string' && j[k]) {
      try {
        const s = j[k].replace(/```(?:json)?/gi, '').trim();
        return JSON.parse(s.slice(s.indexOf('{'), s.lastIndexOf('}') + 1));
      } catch (_) {
        return { besproken: [String(j[k])] };
      }
    }
  }
  const kopie = { ...j };
  delete kopie.pairedItem;
  return Object.keys(kopie).length ? kopie : null;
}

function lijst(v) {
  if (!v) return [];
  return (Array.isArray(v) ? v : [v]).map((x) => (typeof x === 'string' ? x : JSON.stringify(x))).filter(Boolean);
}

const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Prepare Audio').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (handmatig opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

werkJobBij({ status: 'samenvatten', fase: 2 });

// Een model dat graag schrijft, vult elk kopje — ook waar niets over gezegd is —
// met dezelfde paar zinnen ("Er wordt gekeken naar de situatie waarbij een
// artsenverklaring…" stond onder Toezichthouder, Bancaire gevolmachtigde én
// Bijzondere vermogensbestanddelen). De prompt verbiedt het, deze stap dwingt het
// af: een zin die in één deel onder drie of meer kopjes staat is opvulling en
// verdwijnt overal; staat hij onder twee, dan blijft de eerste. Daarna hooguit
// zes punten per kopje, zoals gevraagd.
const MAX_PUNTEN = 6;
function sleutelVan(punt) {
  return String(punt).toLowerCase().replace(/[^a-z0-9À-ÿ]+/g, ' ').trim();
}
// "Er wordt gekeken naar de situatie waarbij…" zegt niet wat eruit kwam en gaat
// weg. "Er wordt besproken dat X" blijft heel: de omhaal eraf knippen laat een
// bijzin met het werkwoord achteraan over ("De gevolmachtigde direct kan handelen").
const LEEG_BEGIN = /^(er|het) wordt (ook |nog )?(gekeken|verwezen|overlegd) (naar|met|of)\b/i;
function zonderOmhaal(punt) {
  const t = String(punt).trim();
  return LEEG_BEGIN.test(t) ? '' : t;
}

function zonderOpvulling(secties) {
  secties = Object.fromEntries(
    Object.entries(secties).map(([kop, waarde]) => [kop, lijst(waarde).map(zonderOmhaal).filter(Boolean)])
  );
  const telling = {};
  for (const waarde of Object.values(secties)) {
    for (const k of new Set(lijst(waarde).map(sleutelVan))) telling[k] = (telling[k] || 0) + 1;
  }
  const gezien = new Set();
  const uit = {};
  for (const [kop, waarde] of Object.entries(secties)) {
    uit[kop] = lijst(waarde)
      .filter((p) => {
        const k = sleutelVan(p);
        if (!k || telling[k] >= 3 || gezien.has(k)) return false;
        gezien.add(k);
        return true;
      })
      .slice(0, MAX_PUNTEN);
  }
  return uit;
}

const delen = [];
const sectiesSamen = {};
let mislukt = 0;
let afgekapt = 0;
const items = $input.all();
items.forEach((item, i) => {
  // Node draait met onError=continueRegularOutput: een blok dat de LLM niet kon
  // samenvatten komt hier binnen met een error-veld in plaats van inhoud.
  if (item.json && item.json.error) {
    mislukt += 1;
    return;
  }
  const obj = haalObject(item.json);
  if (!obj) {
    mislukt += 1;
    return;
  }
  if (obj._afgekapt) {
    afgekapt += 1;
    delete obj._afgekapt;
  }
  // Sjabloon-variant: de blokken leveren hun punten al onder de vaste kopjes.
  // Die worden hier over de blokken heen samengevoegd, zodat de volgorde en de
  // toewijzing niet meer van de verslag-ronde afhangen.
  if (obj.secties && typeof obj.secties === 'object') {
    obj.secties = zonderOpvulling(obj.secties);
    for (const [kop, waarde] of Object.entries(obj.secties)) {
      const punten = lijst(waarde);
      if (!punten.length) continue;
      if (!sectiesSamen[kop]) sectiesSamen[kop] = [];
      for (const punt of punten) {
        // Blokken overlappen niet, maar hetzelfde onderwerp komt soms terug;
        // letterlijke herhaling eruit.
        if (!sectiesSamen[kop].some((b) => b.toLowerCase() === punt.toLowerCase())) {
          sectiesSamen[kop].push(punt);
        }
      }
    }
  }

  obj.afspraken = lijst(obj.afspraken).map(zonderOmhaal).filter(Boolean);
  const regels = [];
  const secties = [
    ['Besproken', obj.besproken],
    ['Afspraken', obj.afspraken],
    ['Namen', obj.namen],
  ];
  for (const [kop, waarde] of secties) {
    const punten = lijst(waarde);
    if (punten.length) regels.push(`${kop}: ${punten.join('; ')}`);
  }
  // Bij de sjabloon-variant vormen de gevulde kopjes zelf de basistekst voor de
  // verslag-ronde; die schrijft daarmee de samenvatting en de titel.
  if (obj.secties && typeof obj.secties === 'object') {
    for (const [kop, waarde] of Object.entries(obj.secties)) {
      const punten = lijst(waarde);
      if (punten.length) regels.push(`${kop}: ${punten.join('; ')}`);
    }
  }
  if (regels.length) delen.push(`--- Deel ${i + 1} ---\n${regels.join('\n')}`);
});

// Vangnet: bij een extreem lange bespreking (ruwweg 2 uur en meer) lopen ook de
// deelsamenvattingen samen het venster uit. Dan zou een tweede reduce-ronde
// nodig zijn; zolang die er niet is, kappen we af én melden we dat.
const MAX_BASIS = 12000;
let basis = delen.join('\n\n');
const basisAfgekapt = basis.length > MAX_BASIS;
if (basisAfgekapt) basis = basis.slice(0, MAX_BASIS) + '\n\n[... deelsamenvattingen afgekapt ...]';

if (!basis) {
  throw new Error(
    `Geen enkel van de ${items.length} transcript-blokken kon worden samengevat.`
  );
}

return [{
  json: {
    basis,
    basis_soort: 'deelsamenvattingen',
    basis_afgekapt: basisAfgekapt,
    // Per kopje samengevoegd over alle blokken; Orden Secties gebruikt dit als
    // primaire bron, want het is completer dan wat de verslag-ronde eruit haalt.
    secties_uit_blokken: Object.keys(sectiesSamen).length ? sectiesSamen : null,
    blokken_mislukt: mislukt,
    blokken_afgekapt: afgekapt,
    blokken_totaal: items.length,
  },
}];

// Korte bespreking: het transcript past in één prompt, dus de map-stap wordt
// overgeslagen en de ruwe tekst gaat rechtstreeks naar de verslag-prompt.
return [{
  json: {
    basis: String($json.transcript || ''),
    basis_soort: 'transcript',
    basis_afgekapt: false,
  },
}];

// Bouwt de prompt voor het besprekingsverslag. De basis is óf het volledige
// transcript (korte bespreking) óf de samengevoegde deelsamenvattingen uit de
// map-stap (lange bespreking); beide takken leveren hetzelfde veld `basis`.
const meta = $('Prepare Audio').first()?.json || {};
const bron = $('Extract Transcript').first()?.json || {};
const invoer = $json || {};

const basis = String(invoer.basis || '');
if (!basis) {
  throw new Error('Geen tekst om een verslag van te maken.');
}

const uitDelen = invoer.basis_soort === 'deelsamenvattingen';
const kopje = uitDelen
  ? `SAMENVATTINGEN PER DEEL (de bespreking is in ${bron.blok_aantal || '?'} delen samengevat)`
  : 'TRANSCRIPT';

// Wie is wie. Het transcript vermeldt geen sprekers, dus zonder deze regels weet
// het model niet over wie het verslag gaat: bij een levenstestament schreef het
// de ziekte en de broer van de cliënt aan de notaris toe. Staat ook zonder namen
// in de prompt — de rolverdeling zelf is het punt.
function rollenBlok(meta) {
  const b = (meta.behandelaars || []).join(', ');
  const c = (meta.clienten || []).join(', ');
  return `ROLLEN
- Behandelaar${b ? ` (${b})` : ''}: medewerker van het notariskantoor. Stelt de vragen en legt de wet uit.
- Cliënten${c ? ` (${c})` : ''}: over hén gaat het verslag — hun familie, gezondheid, vermogen, wensen en keuzes.
- Het transcript zegt niet wie er spreekt. Wie uitlegt en vragen stelt is de behandelaar; wie over het eigen leven vertelt is een cliënt.
- Schrijf nooit iets toe aan de behandelaar of "de notaris" dat over het leven van een mens gaat (ziekte, broer, partner, testament, wensen). Dat gaat altijd over een cliënt; schrijf dan "cliënt" of "cliënten".
- Algemene uitleg van de behandelaar over de wet of over wat er mogelijk is, is geen keuze van de cliënten. Noteer wat voor déze cliënten geldt of wat zij willen.

`;
}

const context = [];
if (meta.onderwerp) context.push(`Onderwerp volgens de behandelaar: ${meta.onderwerp}`);
if (meta.dossier) context.push(`Dossiernummer: ${meta.dossier}`);
// Waarneming van de behandelaar over het verloop van het gesprek. Expliciet
// gelabeld als niet-uit-het-transcript, zodat het model het gebruikt om te
// duiden en niet als besproken punt noteert; het staat verderop sowieso al
// letterlijk in het verslag.
if (meta.context) {
  context.push(
    'Waarnemingen van de behandelaar over het verloop van het gesprek (niet uit het transcript; ' +
      'gebruik ze om het gesprek te duiden, neem ze niet over als besproken punt): ' +
      String(meta.context).replace(/\s*\n\s*/g, ' | ')
  );
}

// Sjabloon voor een testament- of levenstestamentbespreking. Staat er een, dan
// krijgt het model de vaste kopjes mee. De vólgorde wordt hierna alsnog in code
// afgedwongen (Orden Secties); deze aanwijzing dient om de inhoud onder het
// juiste kopje te krijgen, niet om op het model te vertrouwen voor de volgorde.
const fs = require('fs');
const SJABLOON_DIR = '/data/shared/templates/besprekingen';

function laadSjabloon(soort) {
  if (!soort || soort === 'algemeen') return null;
  try {
    const naam = String(soort).replace(/[^a-z]/gi, '').toLowerCase();
    return JSON.parse(fs.readFileSync(`${SJABLOON_DIR}/${naam}.json`, 'utf8'));
  } catch (_) {
    return null;
  }
}

const sjabloon = laadSjabloon(meta.soort);

// Bij een lange bespreking mét sjabloon hebben de blokken de kopjes al gevuld, en
// Orden Secties neemt die als bron. De verslagronde hoeft ze dan niet nog eens
// uit te schrijven: dat was dubbel werk, en bij een model dat ruim formuleert
// liep het antwoord tegen de uitvoerlimiet aan, waarna de JSON ongeldig was en
// samenvatting en afspraken leeg bleven. Ze levert dan alleen wat over het
// geheel gaat.
const alleenKern = uitDelen && sjabloon && Array.isArray(sjabloon.secties);

let sjabloonBlok = '';
if (sjabloon && Array.isArray(sjabloon.secties) && !alleenKern) {
  const regels = sjabloon.secties
    .map((s, i) => `${i + 1}. ${s.kop} — ${s.aanwijzing}`)
    .join('\n');
  sjabloonBlok = `VASTE INDELING (${sjabloon.naam})
Vul "onderwerpen" met exact deze kopjes, in deze volgorde, en gebruik de kop letterlijk zoals hier geschreven. Wat wel is besproken maar nergens onder valt, hoort onder het laatste kopje.

De tekst achter het streepje is een aanwijzing vóór jou over wat er onder dat kopje hoort. Schrijf die aanwijzing NOOIT over als inhoud.

Een kopje krijgt alleen een lege lijst als het onderwerp helemaal niet ter sprake kwam.

${regels}

`;
}

// Geen voorbeeldzinnen in het schema hieronder. Er stond er één bij de
// samenvatting ("het bestaande testament is doorgenomen en blijft in stand…") en
// het model schreef die over als uitkomst van een bespreking waarin het testament
// niet eens op tafel lag.
const chatInput = `Je bent notarieel secretaris. Hieronder staat het materiaal van een bespreking op een notariskantoor. Werk het uit tot een zakelijk verslag.

HARDE REGELS
- Gebruik uitsluitend wat er staat. Verzin geen namen, bedragen, data of afspraken.
- Weet je iets niet, laat het veld dan leeg (lege string of lege lijst). Vul nooit iets aan "voor de volledigheid".
- Het transcript is machinaal gemaakt en kan verhaspelingen bevatten. Neem een naam of bedrag alleen op als die duidelijk uit de tekst blijkt.
- Schrijf in zakelijk Nederlands, derde persoon, verleden tijd.
- Geef alleen geldige JSON terug, zonder toelichting eromheen.

${rollenBlok(meta)}${context.length ? 'CONTEXT\n' + context.join('\n') + '\n' : ''}
${sjabloonBlok}JSON-SCHEMA
{
  "titel": "korte titel van de bespreking",
  "samenvatting": "Begin met waaróver de bespreking ging en wat de cliënten willen regelen. Daarna 4 tot 7 zinnen met de hoofdpunten: wat is gekozen, wat staat nog open. Som geen kopjes op en noem alleen uitkomsten die in het materiaal staan.",
${alleenKern ? '' : `  "onderwerpen": [{"kop": "onderwerp", "punten": ["wat er over gezegd is"]}],
`}  "afspraken": ["wie na dit gesprek wat gaat doen — één actie per regel, met de inhoud erbij"],
  "open_vragen": ["vragen die in de bespreking onbeantwoord bleven"]
}

${kopje}
${basis}`;

return [{
  json: {
    chatInput,
    sjabloon_soort: sjabloon ? sjabloon.soort : null,
    basis_soort: invoer.basis_soort || 'transcript',
    basis_afgekapt: !!invoer.basis_afgekapt,
    blokken_mislukt: invoer.blokken_mislukt || 0,
    blokken_totaal: invoer.blokken_totaal || 1,
  },
}];

// Parseert de LLM-output tot een verslag-object. Faalt de parse, dan levert de
// workflow alsnog een document met alleen het transcript — een mislukte
// samenvatting mag de opname niet weggooien.
const bron = $('Extract Transcript').first()?.json || {};
const prompt = $('Build Verslag Prompt').first()?.json || {};
const meta = $('Prepare Audio').first()?.json || {};

// Met options.format='json' geeft de chainLlm-node het geparste object al als
// $json terug (dus géén .text-veld). Zonder die optie komt de tekst als string
// binnen, eventueel in een markdown-fence. Beide gevallen afvangen.
function haalRuw(j) {
  if (!j || typeof j !== 'object') return '';
  for (const k of ['text', 'output', 'answer', 'response']) {
    if (typeof j[k] === 'string' && j[k]) return j[k];
  }
  if (typeof j?.message?.content === 'string' && j.message.content) return j.message.content;
  const kopie = { ...j };
  delete kopie.pairedItem;
  return Object.keys(kopie).length ? kopie : '';
}

function parseJson(invoer) {
  // Een object zonder inhoudsvelden is geen verslag maar een kale API-respons
  // (lege content, bijvoorbeeld als de uitvoerlimiet opging aan iets anders).
  if (invoer && typeof invoer === 'object') return 'message' in invoer && 'model' in invoer ? null : invoer;
  let s = String(invoer || '').trim();
  const fence = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) s = fence[1].trim();
  const start = s.indexOf('{');
  const eind = s.lastIndexOf('}');
  if (start !== -1 && eind > start) s = s.slice(start, eind + 1);
  try {
    return JSON.parse(s);
  } catch (_) {
    return null;
  }
}

const parsed = parseJson(haalRuw($json));
let parseWaarschuwing = null;

const verslag = parsed && typeof parsed === 'object' ? parsed : {};
if (!parsed) {
  parseWaarschuwing =
    'De samenvatting kon niet als JSON worden gelezen; het verslag bevat alleen het transcript.';
  verslag.titel = 'Besprekingsverslag (samenvatting mislukt)';
  verslag.samenvatting = '';
}

function lijst(v) {
  if (!v) return [];
  return Array.isArray(v) ? v.filter(Boolean) : [v];
}

// Het model houdt zich niet strikt aan "array van strings": afspraken komen er
// geregeld uit als {afspraak, eigenaar, termijn}. Platslaan tot leesbare regels,
// anders belandt "[object Object]" in het document.
function tekst(v) {
  if (v == null) return '';
  if (typeof v !== 'object') return String(v);
  const kern = v.afspraak || v.vraag || v.omschrijving || v.actie || v.punt || v.tekst || v.titel || '';
  const staart = [v.eigenaar || v.wie, v.termijn || v.deadline].filter(Boolean).join(' · ');
  // Onbekende sleutels (open vragen kwamen terug als {vraag, inhoud}): dan de
  // eerste tekstwaarde, nooit de ruwe JSON in het verslag.
  const eersteTekst = Object.values(v).find((x) => typeof x === 'string' && x.trim());
  const basis = String(kern || eersteTekst || JSON.stringify(v));
  return staart ? `${basis}  (${staart})` : basis;
}

const genormaliseerd = {
  titel: String(verslag.titel || '').trim(),
  samenvatting: String(verslag.samenvatting || '').trim(),
  // Aanwezigen komen uitsluitend uit het veld dat de behandelaar invult, niet
  // uit het transcript. Whisper verhaspelt namen, en het model haalde er ook
  // mensen bij die alleen ter sprake kwamen — een erflater of een bank is geen
  // aanwezige. Leeg veld betekent dus geen kopje 'Aanwezig' in het verslag.
  deelnemers: String(meta.deelnemers_invoer || '')
    .split(/[,;\n]/)
    .map((naam) => naam.trim())
    .filter(Boolean)
    .filter((naam, i, alle) => alle.findIndex((n) => n.toLowerCase() === naam.toLowerCase()) === i),
  // Waarnemingen komen letterlijk uit het invoerveld, net als de deelnemers:
  // het is de eigen vastlegging van de behandelaar en het model heeft er niets
  // aan toe te voegen of van af te doen.
  waarnemingen: String(meta.context || '')
    .split(/\n+/)
    .map((regel) => regel.trim())
    .filter(Boolean),
  onderwerpen: lijst(verslag.onderwerpen),
  afspraken: lijst(verslag.afspraken).map(tekst),
  open_vragen: lijst(verslag.open_vragen).map(tekst),
};

return [{
  json: {
    verslag: genormaliseerd,
    transcript: bron.transcript || '',
    blok_aantal: bron.blok_aantal || 1,
    basis_afgekapt: !!prompt.basis_afgekapt,
    blokken_mislukt: prompt.blokken_mislukt || 0,
    parse_waarschuwing: parseWaarschuwing,
    counts: {
      afspraken: genormaliseerd.afspraken.length,
    },
  },
}];

// Dwingt de sjabloonvolgorde af. Het model krijgt de kopjes wel in de prompt,
// maar houdt zich er niet betrouwbaar aan: het laat kopjes weg, hernoemt ze of
// wisselt de volgorde. Daarom hier deterministisch herordenen — dan is het
// verslag van elke testamentbespreking op dezelfde plek te lezen.
//
// Kopjes die niet aan bod kwamen blijven staan met een lege puntenlijst; de
// DOCX-generator zet daar "Niet besproken" onder. Voor een bespreekformulier is
// dat juist waardevol: het laat zien wat nog open staat.
const fs = require('fs');
const meta = $('Prepare Audio').first()?.json || {};
const invoer = $json || {};

function laadSjabloon(soort) {
  if (!soort || soort === 'algemeen') return null;
  try {
    const naam = String(soort).replace(/[^a-z]/gi, '').toLowerCase();
    return JSON.parse(
      fs.readFileSync(`/data/shared/templates/besprekingen/${naam}.json`, 'utf8')
    );
  } catch (_) {
    return null;
  }
}

const sjabloon = laadSjabloon(meta.soort);

// Geen sjabloon (algemene bespreking): alles ongemoeid doorgeven.
if (!sjabloon || !Array.isArray(sjabloon.secties) || !sjabloon.secties.length) {
  return [{ json: { ...invoer, sjabloon_toegepast: null } }];
}

const verslag = { ...(invoer.verslag || {}) };
const gevonden = Array.isArray(verslag.onderwerpen) ? verslag.onderwerpen : [];

function normaliseer(tekst) {
  return String(tekst || '')
    .toLowerCase()
    .replace(/[^a-z0-9À-ſ ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const STOP = new Set(['en', 'de', 'het', 'een', 'van', 'voor', 'bij', 'over']);
function woorden(tekst) {
  return new Set(normaliseer(tekst).split(' ').filter((w) => w.length > 3 && !STOP.has(w)));
}

function past(kopA, kopB) {
  const a = normaliseer(kopA), b = normaliseer(kopB);
  if (!a || !b) return 0;
  if (a === b) return 1;
  if (a.includes(b) || b.includes(a)) return 0.9;
  const A = woorden(a), B = woorden(b);
  if (!A.size || !B.size) return 0;
  let gedeeld = 0;
  for (const w of A) if (B.has(w)) gedeeld += 1;
  return gedeeld / Math.min(A.size, B.size);
}

function puntenVan(onderwerp) {
  if (typeof onderwerp === 'string') return [onderwerp];
  const p = onderwerp?.punten ?? onderwerp?.inhoud;
  if (!p) return [];
  return (Array.isArray(p) ? p : [p]).map((x) => String(x)).filter(Boolean);
}

const nogTeVerdelen = gevonden.map((o) => ({
  kop: typeof o === 'string' ? '' : String(o?.kop || o?.titel || ''),
  punten: puntenVan(o),
}));

// Bij een lange bespreking hebben de blokken hun punten al onder de vaste kopjes
// gezet (zie Split Blokken). Dat is de rijkste bron: die punten zijn gemaakt met
// het volledige transcript-deel in beeld, terwijl de verslag-ronde het met
// samengevatte flarden moet doen. Daarom gaan die eerst.
const transcriptTekst = String(
  ($('Extract Transcript').first()?.json || {}).transcript || ''
).toLowerCase();

let uitBlokken = {};
try {
  uitBlokken = $('Collect Blok Samenvattingen').first()?.json?.secties_uit_blokken || {};
} catch (_) {
  // Korte bespreking: de map-stap heeft niet gedraaid.
}

// Vangnet tegen een lek dat in de praktijk optrad: het model schreef de
// aanwijzing achter een kopje over als inhoud, waardoor "Tweetrapsmaking" gevuld
// leek terwijl het onderwerp nooit ter sprake kwam. Een punt dat vrijwel gelijk
// is aan de aanwijzing van zijn eigen sectie is geen verslag maar een echo.
const alleAanwijzingen = sjabloon.secties.map((s) => String(s.aanwijzing || ''));

// Zelfde vangnet voor de waarneming van de behandelaar. De prompt zegt dat het
// achtergrond is en geen besproken punt, maar dat is precies het soort instructie
// waar dit model overheen leest — en de waarneming staat verderop toch al
// letterlijk in het verslag.
const waarnemingRegels = String(meta.context || '')
  .split(/\n+/)
  .map((r) => r.trim())
  .filter((r) => r.length > 8);

function isEchoVanAanwijzing(punt, eigenAanwijzing) {
  if (past(punt, eigenAanwijzing) >= 0.7) return true;
  if (waarnemingRegels.some((r) => past(punt, r) >= 0.8)) return true;
  return alleAanwijzingen.some((a) => past(punt, a) >= 0.8);
}

// De echo komt ook in stukjes: uit "Medisch aanspreekpunt, behandelverklaringen,
// wel of niet reanimeren, …" maakte het model vier losse punten, en uit de
// trefwoorden van een ander kopje "Geen inboedel", "Geen huisdieren". Zulke
// punten zijn te kort voor de vergelijking hierboven. Wat ze verraadt: ze bestaan
// uit woorden van de aanwijzing die in het gesprek zelf nooit zijn gevallen.
//
// Vergelijken op woordbegin, niet op het hele woord: het model schrijft
// "toezichthouder" waar de cliënt "toezicht" zei, en dat is geen echo.
function valtInTranscript(woord, stam) {
  return transcriptTekst.includes(woord.slice(0, stam));
}

function isFragmentVanAanwijzing(punt) {
  const pw = [...woorden(punt)];
  if (!pw.length) return false;
  return alleAanwijzingen.some((a) => {
    const aw = woorden(a);
    const gedeeld = pw.filter((w) => aw.has(w));
    if (gedeeld.length / pw.length < 0.7) return false;
    // Lang en vrijwel geheel uit de aanwijzing: overgeschreven.
    if (pw.length >= 6) return true;
    const afwezig = gedeeld.filter((w) => !valtInTranscript(w, Math.max(6, w.length - 4)));
    return afwezig.length * 2 >= gedeeld.length;
  });
}

// "Geen inboedel" terwijl het woord inboedel nergens in het gesprek voorkomt: dan
// is er niet vastgesteld dát er geen is, dan is het onderwerp niet besproken.
// Ruim op woordbegin, want een afgewezen keuze ("geen toezichthouder") hoort juist
// wél in het verslag en mag hier niet sneuvelen op een andere woordvorm.
function isOngegrondeOntkenning(punt) {
  const w = losseWoorden(punt);
  if (!/^(geen|niet|nvt|niets)$/.test(w[0] || '')) return false;
  const rest = w.slice(1).filter((x) => x.length > 3 && !VULWOORDEN.has(x));
  return rest.length > 0 && rest.every((x) => !valtInTranscript(x, 6));
}

// Gevraagd om een leeg kopje leeg te laten, schrijft het model er geregeld
// "geen bespreking" of "niet besproken" in. Dat is geen inhoud maar een lege
// lijst in woorden; hier wordt het weer een echt leeg kopje, zodat het verslag
// overal dezelfde formulering gebruikt.
// Strikt: alleen een kále mededeling dat er niets is besproken gaat eruit.
// Eerder was dit ruimer en sneuvelde ook "Geen bewind; wel een toelichting in het
// concept" — precies de afgewezen keuze die wél in het verslag hoort.
const KAAL_LEEG = /^(niet|geen)\s+(besproken|bespreking|aan de orde|aan bod|van toepassing|genoemd|vermeld|gezegd|behandeld|vastgelegd|ingevuld|opgenomen|gekozen|afgesproken|ter sprake gekomen|ter sprake|aan bod gekomen)$/i;
const KAAL_NVT = /^(nvt|n\.?v\.?t\.?|onbekend|niets|geen|niet)$/i;

// Het model verzint eindeloos nieuwe manieren om "hier staat niets" te zeggen:
// "Niet besproken", "Niet ter sprake gekomen", "Geen specifieke voogdij". Een
// woordenlijst bijhouden is dweilen. Deze regel generaliseert: begint het punt
// met een ontkenning en blijft er ná het wegstrepen van de kopwoorden niets
// inhoudelijks over, dan staat er niets. "Geen bewind; wel een toelichting in
// het concept" houdt wél inhoud over en blijft dus staan.
const VULWOORDEN = new Set([
  'de','het','een','van','en','voor','bij','over','er','is','zijn','wordt',
  'worden','of','specifieke','specifiek','aparte','apart','nadere','verdere',
]);

function losseWoorden(tekst) {
  return String(tekst).toLowerCase().replace(/[^a-z0-9À-ÿ ]+/g, ' ').split(/\s+/).filter(Boolean);
}

function zegtAlleenNiets(punt, kop) {
  const w = losseWoorden(punt);
  if (!w.length) return true;
  if (!/^(geen|niet|nvt|niets)$/.test(w[0])) return false;
  const kopWoorden = new Set(losseWoorden(kop));
  return w.slice(1).filter((x) => !VULWOORDEN.has(x) && !kopWoorden.has(x) && x.length > 2).length === 0;
}

const koppenLaag = new Set(sjabloon.secties.map((s) => String(s.kop).toLowerCase()));

function isLegeMelding(punt) {
  const t = String(punt || '').trim().replace(/[.;:!]+$/, '');
  if (!t) return true;
  // Eén los woord ("Huisdieren", "Kosten") is een trefwoord, geen verslag.
  if (losseWoorden(t).length < 2) return true;
  // "Kosten: niet genoemd", "Planning: overige aandachtspunten" — een etiket met
  // erachter de mededeling dat er niets is, of de naam van een kopje.
  const zonderEtiket = t.replace(/^[^:]{1,40}:\s*/, '');
  if (
    zonderEtiket !== t &&
    (KAAL_NVT.test(zonderEtiket) || KAAL_LEEG.test(zonderEtiket) || koppenLaag.has(zonderEtiket.toLowerCase()))
  ) {
    return true;
  }
  if (t.length > 30) return false;
  return KAAL_NVT.test(t) || KAAL_LEEG.test(t);
}

const geordend = sjabloon.secties.map((sectie) => {
  let punten = [];

  // 1. Wat de blokken onder dit kopje zetten.
  for (const [kop, waarde] of Object.entries(uitBlokken)) {
    if (past(sectie.kop, kop) >= 0.6 && Array.isArray(waarde)) {
      punten.push(...waarde.map((x) => String(x)));
    }
  }

  // 2. Aangevuld met wat de verslag-ronde onder hetzelfde kopje zette.
  for (let i = nogTeVerdelen.length - 1; i >= 0; i--) {
    if (past(sectie.kop, nogTeVerdelen[i].kop) >= 0.6) {
      for (const punt of nogTeVerdelen[i].punten) {
        if (!punten.some((b) => past(b, punt) >= 0.7)) punten.push(punt);
      }
      nogTeVerdelen.splice(i, 1);
    }
  }

  punten = punten.filter(
    (p) =>
      !isLegeMelding(p) &&
      !zegtAlleenNiets(p, sectie.kop) &&
      !isEchoVanAanwijzing(p, sectie.aanwijzing || '') &&
      !isFragmentVanAanwijzing(p) &&
      !isOngegrondeOntkenning(p)
  );

  // Het model zet er soms "Geen specifieke wijzigingen besproken" bóven een lijst
  // mét wijzigingen. Zo'n regel spreekt de rest van het kopje tegen; weg ermee,
  // maar alléén als er inhoud naast staat. Is het het enige punt, dan is het
  // gewoon de mededeling dat er niets was.
  if (punten.length > 1) {
    const ZEGT_NIETS = /^(er (is|zijn|was|waren) )?(geen|niets|niet)\b[^.]{0,60}\b(besproken|genoemd|vermeld|vastgelegd|aan de orde|gekozen|afgesproken)/i;
    const inhoudelijk = punten.filter((p) => !ZEGT_NIETS.test(String(p).trim()));
    if (inhoudelijk.length) punten = inhoudelijk;
  }

  // Vangnet voor een onderwerp dat wél ter sprake kwam maar waar het model niets
  // van maakte — typisch wanneer ervan wordt afgezien ("de vaccinatieclausule?
  // nee, laat maar zitten"). Vragen om dat toch te noteren hielp niet: gemeten
  // bleef het kopje leeg. Deterministisch signaleren dat het woord in het
  // transcript valt is wél betrouwbaar, en voor een bespreekformulier is "hier is
  // over gesproken, kijk even" bruikbaarder dan een kopje dat suggereert dat het
  // onderwerp nooit langskwam.
  let terSprake = null;
  if (!punten.length) {
    terSprake = (sectie.trefwoorden || []).find((w) =>
      transcriptTekst.includes(String(w).toLowerCase())
    ) || null;
  }

  return {
    kop: sectie.kop,
    punten,
    niet_besproken: punten.length === 0,
    ter_sprake: terSprake,
  };
});

// Wat nergens op paste gaat naar het laatste kopje van het sjabloon, met de
// oorspronkelijke kop ervoor zodat er niets zoekraakt.
const rest = [];
for (const over of nogTeVerdelen) {
  for (const punt of over.punten) {
    rest.push(over.kop ? `${over.kop}: ${punt}` : punt);
  }
}
if (rest.length) {
  const laatste = geordend[geordend.length - 1];
  laatste.punten.push(...rest);
  laatste.niet_besproken = false;
}

// Het laatste kopje is de vergaarbak, en het model gebruikt het ook zo: wat al
// onder "Schenkingsbevoegdheid" staat, zet het er nog eens neer. Wat elders in
// het verslag al staat, hoeft daar niet opnieuw.
{
  const laatste = geordend[geordend.length - 1];
  const elders = geordend.slice(0, -1).flatMap((o) => o.punten);
  laatste.punten = laatste.punten.filter((p) => !elders.some((e) => past(e, p) >= 0.7));
  laatste.niet_besproken = laatste.punten.length === 0;
}

verslag.onderwerpen = geordend;

return [{
  json: {
    ...invoer,
    verslag,
    // Welke kopjes langs de nacontrole moeten: leeg-maar-wel-ter-sprake, plus de
    // kopjes die in het sjabloon als `altijd_nacontrole` staan. Dat laatste is
    // er voor "Gewenste wijzigingen": daar ging de brede prompt structureel de
    // mist in door een besproken-maar-afgewezen optie als wijziging te noteren.
    nacontrole_koppen: geordend
      .filter((o) => {
        const sec = sjabloon.secties.find((s) => s.kop === o.kop) || {};
        if (sec.altijd_nacontrole) return true;
        return !(o.punten || []).length && o.ter_sprake;
      })
      .map((o) => o.kop),
    sjabloon_toegepast: sjabloon.soort,
    sjabloon_secties: Object.fromEntries(
      sjabloon.secties.map((sec) => [
        sec.kop,
        { aanwijzing: sec.aanwijzing || '', trefwoorden: sec.trefwoorden || [] },
      ])
    ),
    secties_totaal: geordend.length,
    secties_besproken: geordend.filter((s) => !s.niet_besproken).length,
    secties_ondergebracht_bij_overig: rest.length,
  },
}];

// Bouwt één gerichte vraag per kopje dat Orden Secties heeft aangewezen.
//
// Twee soorten: kopjes die leeg bleven terwijl hun trefwoord wél viel, en
// kopjes die in het sjabloon als `altijd_nacontrole` staan omdat de brede prompt
// ze structureel verkeerd invult. Alleen de fragmenten rond het trefwoord gaan
// mee, niet het hele transcript: dat houdt de prompt klein en de aandacht op de
// juiste plek.
const VENSTER = 700;
const MAX_FRAGMENTEN = 3;

const invoer = $json || {};
const bron = $('Extract Transcript').first()?.json || {};
const transcript = String(bron.transcript || '');
const laag = transcript.toLowerCase();

// Wie is wie. Het transcript vermeldt geen sprekers, dus zonder deze regels weet
// het model niet over wie het verslag gaat: bij een levenstestament schreef het
// de ziekte en de broer van de cliënt aan de notaris toe. Staat ook zonder namen
// in de prompt — de rolverdeling zelf is het punt.
function rollenBlok(meta) {
  const b = (meta.behandelaars || []).join(', ');
  const c = (meta.clienten || []).join(', ');
  return `ROLLEN
- Behandelaar${b ? ` (${b})` : ''}: medewerker van het notariskantoor. Stelt de vragen en legt de wet uit.
- Cliënten${c ? ` (${c})` : ''}: over hén gaat het verslag — hun familie, gezondheid, vermogen, wensen en keuzes.
- Het transcript zegt niet wie er spreekt. Wie uitlegt en vragen stelt is de behandelaar; wie over het eigen leven vertelt is een cliënt.
- Schrijf nooit iets toe aan de behandelaar of "de notaris" dat over het leven van een mens gaat (ziekte, broer, partner, testament, wensen). Dat gaat altijd over een cliënt; schrijf dan "cliënt" of "cliënten".
- Algemene uitleg van de behandelaar over de wet of over wat er mogelijk is, is geen keuze van de cliënten. Noteer wat voor déze cliënten geldt of wat zij willen.

`;
}
const rollen = rollenBlok($('Prepare Audio').first()?.json || {});

const meta = invoer.sjabloon_secties || {};
const koppen = invoer.nacontrole_koppen || [];
const perKop = Object.fromEntries(
  (invoer.verslag?.onderwerpen || []).map((o) => [o.kop, o])
);

function fragmenten(trefwoorden) {
  const stukken = [];
  for (const woord of trefwoorden || []) {
    const w = String(woord).toLowerCase();
    let vanaf = 0;
    while (stukken.length < MAX_FRAGMENTEN) {
      const i = laag.indexOf(w, vanaf);
      if (i === -1) break;
      stukken.push(transcript.slice(Math.max(0, i - VENSTER), i + VENSTER).trim());
      vanaf = i + w.length;
    }
    if (stukken.length >= MAX_FRAGMENTEN) break;
  }
  return stukken;
}

return koppen.map((kop) => {
  const sec = meta[kop] || {};
  const trefwoorden = sec.trefwoorden && sec.trefwoorden.length
    ? sec.trefwoorden
    : [perKop[kop]?.ter_sprake].filter(Boolean);
  const stukken = fragmenten(trefwoorden);
  const vraag = sec.vraag || `Wat is er in deze bespreking gezegd over: ${kop}?`;

  return {
    json: {
      nacontroleKop: kop,
      chatInput: `Hieronder staan fragmenten uit een transcript van een notariële bespreking.

VRAAG
${vraag}
${sec.vraag ? '' : (sec.aanwijzing ? `Ter oriëntatie, wat er onder dit kopje kán vallen (dit is geen antwoord; neem er niets uit over dat niet in de fragmenten staat): ${sec.aanwijzing}` : '')}

${rollen}REGELS
- Antwoord alleen op basis van de fragmenten. Verzin niets.
- Schrijf op wat de cliënten hierover zeiden of kozen, met de inhoud erbij. Een opsomming van onderwerpen is geen antwoord.
- Gaat het onderwerp in deze fragmenten ergens anders over, geef dan een lege lijst.
- Hooguit drie korte zinnen.

Geef alleen geldige JSON terug:
{"punten": ["korte zin"]}

FRAGMENTEN
${stukken.join('\n\n[...]\n\n')}`,
    },
  };
});

// Teken van leven per nagecontroleerd kopje.
const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Prepare Audio').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (handmatig opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

const totaal = $('Split Nacontrole').all().length;
werkJobBij({
  status: 'nacontrole',
  fase: 2,
  nacontrole_voortgang: `${$runIndex + 1}/${totaal}`,
});

return $input.all();

// Vouwt de antwoorden van de nacontrole terug in het verslag.
const basis = $('Orden Secties').first()?.json || {};
const verslag = { ...(basis.verslag || {}) };
const koppen = $('Split Nacontrole').all().map((i) => i.json.nacontroleKop);

function haalObject(j) {
  if (!j || typeof j !== 'object') return null;
  // Rechtstreekse Ollama-aanroep: het antwoord staat als tekst in message.content.
  if (typeof j?.message?.content === 'string') {
    try {
      const t = j.message.content.replace(/```(?:json)?/gi, '').trim();
      return JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
    } catch (_) {
      return null;
    }
  }
  for (const k of ['text', 'output', 'answer', 'response']) {
    if (typeof j[k] === 'string' && j[k]) {
      try {
        const t = j[k].replace(/```(?:json)?/gi, '').trim();
        return JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
      } catch (_) {
        return null;
      }
    }
  }
  const kopie = { ...j };
  delete kopie.pairedItem;
  return Object.keys(kopie).length ? kopie : null;
}

// Het model antwoordt soms óver de vraag in plaats van erop: "bevindt zich niet
// in de gegeven fragmenten", of het herhaalt de kop en zegt dat het onderwerp
// niet is besproken. Dat is geen inhoud; dan blijft het kopje beter gemarkeerd
// als "kwam ter sprake" dan dat er een schijnantwoord in het verslag staat.
const GEEN_ANTWOORD = /(fragment|niet in de gegeven|geen informatie|komt niet voor|wordt niet genoemd|niet vermeld|niet besproken|geen (van de )?punten|onbekend)/i;

// Zelfde vangnet als in Orden Secties, hier het hardst nodig: de nacontrole
// krijgt de aanwijzing van het kopje mee en gaf die terug als antwoord, als geheel
// ("…bijvoorbeeld de kinderen samen", bij cliënten zonder kinderen) of in stukjes
// ("Wel of niet reanimeren"). Een punt dat uit woorden van de aanwijzing bestaat
// die in het gesprek niet zijn gevallen, is geen antwoord.
const transcriptLaag = String(
  ($('Extract Transcript').first()?.json || {}).transcript || ''
).toLowerCase();
const aanwijzingen = Object.values(basis.sjabloon_secties || {}).map((s) => String(s.aanwijzing || ''));
const STOP = new Set(['en', 'de', 'het', 'een', 'van', 'voor', 'bij', 'over']);
function woorden(tekst) {
  return new Set(
    String(tekst || '').toLowerCase().replace(/[^a-z0-9À-ſ ]+/g, ' ').split(/\s+/)
      .filter((w) => w.length > 3 && !STOP.has(w))
  );
}
function isEchoVanAanwijzing(punt) {
  const pw = [...woorden(punt)];
  if (!pw.length) return false;
  return aanwijzingen.some((a) => {
    const aw = woorden(a);
    const gedeeld = pw.filter((w) => aw.has(w));
    if (gedeeld.length / pw.length < 0.7) return false;
    if (pw.length >= 6) return true;
    const afwezig = gedeeld.filter(
      (w) => !transcriptLaag.includes(w.slice(0, Math.max(6, w.length - 4)))
    );
    return afwezig.length * 2 >= gedeeld.length;
  });
}

const gevonden = {};
$input.all().forEach((item, i) => {
  if (item.json && item.json.error) return;
  const kop = koppen[i];
  const obj = haalObject(item.json);
  const punten = (obj && Array.isArray(obj.punten) ? obj.punten : [])
    .map((x) => String(x).trim())
    .filter((x) => x.length > 8)
    .filter((x) => !GEEN_ANTWOORD.test(x))
    .filter((x) => !isEchoVanAanwijzing(x))
    // Een punt dat alleen de kop herhaalt zegt niets.
    .filter((x) => x.toLowerCase().replace(/[^a-z ]/g, '').trim() !== String(kop || '').toLowerCase());
  if (punten.length && kop) gevonden[kop] = punten;
});

verslag.onderwerpen = (verslag.onderwerpen || []).map((o) => {
  const extra = gevonden[o.kop];
  if (!extra) return o;
  return { ...o, punten: extra, niet_besproken: false, ter_sprake: null, uit_nacontrole: true };
});

return [{
  json: {
    ...basis,
    verslag,
    nacontrole_gevraagd: koppen.length,
    nacontrole_gevuld: Object.keys(gevonden).length,
  },
}];

// Kern van de getalcontrole, los getest voordat hij de workflow in gaat.
//
// Doel: elk getal dat in het verslag staat moet terug te vinden zijn in het
// transcript. Lastig punt is dat Whisper getallen nu eens als cijfer schrijft
// ("60%", "2008") en dan weer voluit ("vierhonderdvijftigduizend", "twintig
// procent"). Daarom wordt van elk getal ook de Nederlandse woordvorm gemaakt en
// dáárop gezocht.

const EENHEDEN = [
  'nul', 'een', 'twee', 'drie', 'vier', 'vijf', 'zes', 'zeven', 'acht', 'negen',
  'tien', 'elf', 'twaalf', 'dertien', 'veertien', 'vijftien', 'zestien',
  'zeventien', 'achttien', 'negentien',
];
const TIENTALLEN = [
  '', '', 'twintig', 'dertig', 'veertig', 'vijftig', 'zestig', 'zeventig',
  'tachtig', 'negentig',
];

function onder100(n) {
  if (n < 20) return EENHEDEN[n];
  const t = Math.floor(n / 10);
  const e = n % 10;
  if (!e) return TIENTALLEN[t];
  // Nederlands zet de eenheid vóór het tiental: 45 = vijfenveertig.
  const koppel = EENHEDEN[e].endsWith('e') ? 'ën' : 'en';
  return `${EENHEDEN[e]}${koppel}${TIENTALLEN[t]}`;
}

function onder1000(n) {
  if (n < 100) return onder100(n);
  const h = Math.floor(n / 100);
  const rest = n % 100;
  const kop = h === 1 ? 'honderd' : `${EENHEDEN[h]}honderd`;
  return rest ? `${kop}${onder100(rest)}` : kop;
}

/** Nederlandse woordvorm van een geheel getal, of null buiten bereik. */
function inWoorden(n) {
  if (!Number.isInteger(n) || n < 0 || n > 999999999) return null;
  if (n < 1000) return onder1000(n);
  if (n < 1000000) {
    const d = Math.floor(n / 1000);
    const rest = n % 1000;
    const kop = d === 1 ? 'duizend' : `${onder1000(d)}duizend`;
    return rest ? `${kop}${onder1000(rest)}` : kop;
  }
  const m = Math.floor(n / 1000000);
  const rest = n % 1000000;
  const kop = m === 1 ? 'een miljoen' : `${onder1000(m)} miljoen`;
  return rest ? `${kop} ${inWoorden(rest)}` : kop;
}

/** Alle schrijfwijzen waarop dit getal in een transcript kan staan. */
function varianten(n, ruw) {
  const uit = new Set();
  if (ruw) uit.add(String(ruw).toLowerCase());
  uit.add(String(n));
  // Duizendtallen met punt of spatie, zoals Whisper ze soms zet.
  if (n >= 1000) {
    uit.add(n.toLocaleString('nl-NL'));
    uit.add(String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ' '));
  }
  const woorden = inWoorden(n);
  if (woorden) {
    uit.add(woorden);
    // Whisper schrijft samenstellingen vaak los: "tweeduizend acht".
    uit.add(woorden.replace(/duizend/g, 'duizend '));
    uit.add(woorden.replace(/honderd/g, 'honderd '));
  }
  return [...uit].map((v) => v.trim()).filter(Boolean);
}

/**
 * Zoekt getallen in een tekst. Levert per vondst het ruwe fragment en de
 * numerieke waarde. Jaartallen en losse kleine getallen tellen mee; die kunnen
 * net zo goed verzonnen zijn.
 */
function vindGetallen(tekst) {
  const gevonden = [];
  const rx = /(\d{1,3}(?:[.\s]\d{3})+|\d+)(?:[,.](\d+))?\s*(%|procent|euro)?/gi;
  let m;
  while ((m = rx.exec(String(tekst || ''))) !== null) {
    const heel = m[1].replace(/[.\s]/g, '');
    const waarde = parseInt(heel, 10);
    if (!Number.isFinite(waarde)) continue;
    gevonden.push({ ruw: m[0].trim(), heelGetal: waarde, eenheid: (m[3] || '').toLowerCase() });
  }
  return gevonden;
}

function ontsnap(tekst) {
  return String(tekst).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * True als het getal ergens in het transcript terug te vinden is.
 *
 * Op woordgrenzen en niet als losse substring: anders gold "100" als gedekt
 * omdat "honderd" toevallig in "zeshonderd" zit, en "18" omdat het in "2018"
 * staat. Zo'n valse zekerheid maakt de hele controle waardeloos.
 */
function staatInTranscript(getal, transcriptLaag) {
  return varianten(getal.heelGetal, String(getal.heelGetal)).some((v) => {
    const kaal = v.toLowerCase().trim();
    if (!kaal) return false;
    const alleenCijfers = /^[\d.,\s]+$/.test(kaal);
    // Een punt of komma direct ná het getal is meestal leesteken ("in 2008."),
    // dus die mag; alleen een aangrenzend cijfer betekent dat we in een gróter
    // getal zitten (201 in 2018, of een decimaal deel).
    const patroon = alleenCijfers
      ? new RegExp(`(?<!\\d)(?<!\\d[.,])${ontsnap(kaal)}(?!\\d)(?![.,]\\d)`)
      : new RegExp(`\\b${ontsnap(kaal)}\\b`);
    return patroon.test(transcriptLaag);
  });
}

// ---------------------------------------------------------------------------
// Elk getal in het verslag moet terug te vinden zijn in het transcript. Zo niet,
// dan komt er een markering achter. Reden: van alle fouten die dit model maakt,
// is een verkeerd bedrag de gevaarlijkste — een verkeerd geplaatst kopje ziet de
// behandelaar zo, een plausibel ogend bedrag niet.
//
// Wat dit wél vangt: verzonnen en verrekende getallen (120.000 + 60.000 werd
// "216.000"). Wat het níét vangt: een getal dat wél in het transcript staat maar
// verkeerd is begrepen — "95, 96" (bouwjaar) dat "95% van de woning" wordt.
const basis = $json || {};
const verslag = { ...(basis.verslag || {}) };
const transcriptLaag = String(
  ($('Extract Transcript').first()?.json || {}).transcript || ''
).toLowerCase();

let gemarkeerd = 0;

let controleer = function (tekst) {
  const t = String(tekst || '');
  if (!t) return t;
  const onvindbaar = vindGetallen(t)
    .filter((g) => !staatInTranscript(g, transcriptLaag))
    .map((g) => g.ruw);
  if (!onvindbaar.length) return t;
  gemarkeerd += onvindbaar.length;
  const uniek = [...new Set(onvindbaar)];
  return `${t}  [niet in transcript: ${uniek.join(', ')}]`;
};

function controleerLijst(lijst) {
  return (Array.isArray(lijst) ? lijst : []).map((x) =>
    typeof x === 'string' ? controleer(x) : x
  );
}

// Tweede controle, zelfde gedachte: iets persoonlijks dat aan de notaris wordt
// toegeschreven. De prompts leggen de rolverdeling uit, maar het transcript
// vermeldt geen sprekers en dit model las er al eens overheen: "de broer van de
// notaris als gevolmachtigde", "ziekte van Huntington (bij de notaris)". Zo'n zin
// leest als een feit en hoort dus een markering te krijgen. Niet herschrijven —
// wie er werkelijk bedoeld is, weet alleen de behandelaar.
const rolMeta = $('Prepare Audio').first()?.json || {};
const wieNiet = ['notaris', 'kandidaat-notaris', 'behandelaar']
  .concat((rolMeta.behandelaars || []).map((n) => ontsnap(String(n).trim())).filter(Boolean))
  .join('|');
const ROL_VAN = new RegExp(
  `\\b(broers?|zus(?:sen|ters?)?|partner|echtgeno(?:ot|te)|kind(?:eren)?|ouders?|vader|moeder|` +
    `testament|levenstestament|woning|vermogen|wens(?:en)?)\\s+van\\s+(?:de\\s+)?(?:${wieNiet})(?![\\wÀ-ÿ])`,
  'i'
);
const ROL_ZIEK = new RegExp(
  `\\b(ziekte|dementie|diagnose)[^.;]{0,40}?\\(?\\b(?:van|bij)\\s+(?:de\\s+)?(?:${wieNiet})(?![\\wÀ-ÿ])`,
  'i'
);
const ROL_KAN_NIET = new RegExp(
  `\\b(?:de\\s+)?(?:${wieNiet})\\s+(?:zelf\\s+)?(?:niet meer (?:kan|kunnen)|wilsonbekwaam|ziek\\b|komt te overlijden|overlijdt)`,
  'i'
);
let rolGemarkeerd = 0;
const basisControleer = controleer;
controleer = function (tekst) {
  const t = basisControleer(tekst);
  if (!t || !(ROL_VAN.test(t) || ROL_ZIEK.test(t) || ROL_KAN_NIET.test(t))) return t;
  rolGemarkeerd += 1;
  return `${t}  [controleer: dit gaat over een cliënt, niet over de notaris]`;
};

verslag.samenvatting = controleer(verslag.samenvatting);
verslag.afspraken = controleerLijst(verslag.afspraken);
verslag.open_vragen = controleerLijst(verslag.open_vragen);
verslag.onderwerpen = (verslag.onderwerpen || []).map((o) => ({
  ...o,
  punten: controleerLijst(o.punten),
}));

return [{ json: { ...basis, verslag, getallen_gemarkeerd: gemarkeerd, rol_gemarkeerd: rolGemarkeerd } }];

// Args naar tijdelijk JSON-bestand voor genereer_besprekingsverslag.py. Zelfde
// patroon als de analyse-flow: het transcript bevat cliëntgegevens en gaat
// daarom niet via de commandline. Python verwijdert het bestand na inlezen.
const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Prepare Audio').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (handmatig opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

werkJobBij({ status: 'document', fase: 3 });

const execId = String($execution.id || 'single').replace(/[^0-9A-Za-z_-]/g, '_').slice(0, 32);
const argsFile = `/tmp/n8n_args_bespreking_${execId}_${Date.now()}.json`;

const meta = $('Prepare Audio').first()?.json || {};
const j = $json || {};

const payload = {
  verslag: j.verslag || {},
  referentie: String(meta.referentie || 'onbekend'),
  transcript: String(j.transcript || ''),
  metadata: {
    dossier: meta.dossier || '',
    datum: meta.datum || '',
    duur_seconden: meta.duur_seconden || 0,
  },
};

fs.writeFileSync(argsFile, JSON.stringify(payload), 'utf8');
return [{ json: { ...j, argsFile } }];

// Schrijft het eindresultaat in het jobbestand; de webapp haalt het bij de
// volgende poll op. De HTTP-respons is al veel eerder verstuurd (job_id), dus
// hier gaat niets meer over de lijn.
const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Prepare Audio').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (handmatig opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

const cmd = $('Generate Verslag DOCX').first()?.json || {};
const stdout = String(cmd.stdout || '');
const stderr = String(cmd.stderr || '');
const match = stdout.match(/SUCCESS:\s*(.+)/);
const filePath = match ? match[1].trim() : '';
const filename = filePath ? filePath.split('/').pop() : '';

// Let op: pak hier altijd de láátste bewerking van het verslag. Write Verslag
// Args leest `$json` en krijgt die vanzelf, maar deze node haalt zijn data via
// nodenamen op — vergeet je die bij te werken als er een stap bij komt, dan
// bevat het DOCX de nieuwe versie en de webapp de oude. Dat is hier al twee keer
// misgegaan bij het toevoegen van een nabewerking.
// Uit Write Verslag Args: die node draait altijd en als laatste, welke tak er
// ook is gevolgd. Eerder stond hier een keten van nodenamen, en dat ging drie
// keer mis — het DOCX kreeg de nieuwste versie en de webapp een oudere.
const data = $('Write Verslag Args').first()?.json || {};
const meta = $('Prepare Audio').first()?.json || {};

const waarschuwingen = [];
if (data.parse_waarschuwing) waarschuwingen.push(data.parse_waarschuwing);
if (data.blokken_mislukt) {
  waarschuwingen.push(
    `${data.blokken_mislukt} van de ${data.blok_aantal} delen van de bespreking konden niet worden samengevat en zijn niet in het verslag verwerkt. Het volledige transcript staat wel in de bijlage.`
  );
}
let delenAfgekapt = 0;
try {
  delenAfgekapt = $('Collect Blok Samenvattingen').first()?.json?.blokken_afgekapt || 0;
} catch (_) {
  // Korte bespreking: de map-stap heeft niet gedraaid.
}
if (delenAfgekapt) {
  waarschuwingen.push(
    `Bij ${delenAfgekapt} van de ${data.blok_aantal} delen is het antwoord van het model afgekapt; wat er stond is bewaard, maar het laatste stuk van dat deel kan ontbreken.`
  );
}
if (data.basis_afgekapt) {
  waarschuwingen.push(
    'De bespreking was zo lang dat zelfs de deelsamenvattingen niet in één prompt pasten; het laatste stuk is niet meegewogen. Het volledige transcript staat wel in de bijlage.'
  );
}
// Kwaliteit van het transcript. Een verslag kan er verzorgd uitzien terwijl de
// helft van het gesprek er niet in zit; dat hoort de behandelaar te weten vóór
// die erop vertrouwt.
const tr = $('Extract Transcript').first()?.json || {};
if (tr.transcript_lussen) {
  waarschuwingen.push(
    `Op ${tr.transcript_lussen} plek(ken) liep de transcriptie vast in een herhaling; daar ontbreekt gesproken tekst. Zoek in het transcript naar "× herhaald" en vul wat daar besproken is zo nodig zelf aan.`
  );
}
const woordenTotaal = String(data.transcript || '').split(/\s+/).filter(Boolean).length;
const minuten = (meta.duur_seconden || 0) / 60;
const woordenPerMinuut = meta.heeftAudio && minuten >= 3 ? Math.round(woordenTotaal / minuten) : null;
// Een gesprek haalt 130 tot 160 woorden per minuut. Ruim daaronder is er spraak
// niet opgevangen — in de praktijk de cliënt die verder van de microfoon zit.
if (woordenPerMinuut !== null && woordenPerMinuut < 105) {
  waarschuwingen.push(
    `Het transcript is dun: ${woordenPerMinuut} woorden per minuut, waar een gesprek er meestal 130 tot 160 haalt. Waarschijnlijk is een deel van wat er is gezegd niet opgevangen, vooral van wie zacht sprak of verder van de microfoon zat.`
  );
}
if (data.rol_gemarkeerd) {
  waarschuwingen.push(
    `${data.rol_gemarkeerd} zin(nen) schrijven iets persoonlijks toe aan de notaris of behandelaar. Dat gaat vrijwel zeker over een cliënt; zie de markeringen.`
  );
}
if (!filePath) {
  waarschuwingen.push(
    `Verslag-DOCX niet gegenereerd. stdout=${stdout.slice(0, 200)}; stderr=${stderr.slice(0, 200)}`
  );
}

const resultaat = {
  success: !!filePath,
  referentie: meta.referentie || '',
  dossier: meta.dossier || '',
  datum: meta.datum || '',
  duur_seconden: meta.duur_seconden || 0,
  filename: filename || null,
  file_path: filePath || null,
  download_url: filename ? `/output/${filename}` : null,
  verslag: data.verslag || null,
  transcript: data.transcript || '',
  blok_aantal: data.blok_aantal || 1,
  getallen_gemarkeerd: data.getallen_gemarkeerd || 0,
  transcript_kwaliteit: {
    woorden_per_minuut: woordenPerMinuut,
    herhalingslussen: tr.transcript_lussen || 0,
    zinnen_geschrapt: tr.transcript_zinnen_geschrapt || 0,
  },
  sjabloon: data.sjabloon_toegepast
    ? {
        soort: data.sjabloon_toegepast,
        secties_totaal: data.secties_totaal || 0,
        secties_besproken: data.secties_besproken || 0,
      }
    : null,
  counts: data.counts || null,
  waarschuwingen,
};

const job = werkJobBij({
  status: filePath ? 'klaar' : 'fout',
  fase: 4,
  fout: filePath ? null : waarschuwingen.join(' '),
  resultaat,
});

return [{ json: job }];

// ---------------------------------------------------------------------------
// Aanvullen van een besprekingsverslag door de behandelaar.
//
// Een kopje uit het sjabloon kan leeg blijven terwijl het onderwerp wél is
// besproken — het transcript mist het, of het model haalt er niets uit. Hier
// vult de behandelaar dat alsnog in, waarna het DOCX opnieuw wordt gemaakt.
//
// Er komt geen model aan te pas: genereer_besprekingsverslag.py is een zuivere
// functie van het verslag. De bron blijft het jobbestand op schijf, dus de
// webapp stuurt alleen het job_id en de aanvullingen mee — het transcript en de
// rest van het verslag hoeven daarvoor niet opnieuw over de lijn.
//
// Verwacht multipart-form-data met één veld 'payload' (JSON-tekst):
//   { job_id, aanvullingen: { "<kop>": ["punt", ...] } }
// ---------------------------------------------------------------------------

const fs = require('fs');
const JOB_DIR = '/data/shared/jobs';

// Een throw in een Code node levert bij responseMode=responseNode een leeg
// 200-antwoord op; verwachte fouten gaan daarom als data terug.
function mislukt(bericht) {
  return [{ json: { success: false, error: bericht } }];
}

const body = $json.body || $json || {};
let payload;
try {
  payload = typeof body.payload === 'string' ? JSON.parse(body.payload) : (body.payload || body);
} catch (err) {
  return mislukt(`Kon payload niet lezen als JSON: ${err.message}`);
}

const jobId = String(payload.job_id || '').trim();
if (!/^[0-9A-Za-z_-]{1,120}$/.test(jobId)) {
  return mislukt(`Ongeldig job_id: '${payload.job_id || ''}'.`);
}

const jobPad = `${JOB_DIR}/${jobId}.json`;
let job;
try {
  job = JSON.parse(fs.readFileSync(jobPad, 'utf8'));
} catch (err) {
  return mislukt(
    `Kon de bespreking niet meer vinden (${err.code || 'fout'}). Jobbestanden worden na 24 uur ` +
    `opgeruimd; genereer het verslag opnieuw om het te kunnen aanvullen.`
  );
}

const resultaat = job.resultaat || null;
const verslag = resultaat && resultaat.verslag ? resultaat.verslag : null;
if (!verslag || !Array.isArray(verslag.onderwerpen)) {
  return mislukt('Deze bespreking heeft nog geen verslag met kopjes om aan te vullen.');
}

// Aanvullingen normaliseren: per kop een lijst korte regels. Lege regels eruit,
// zodat een per ongeluk achtergelaten witregel geen leeg opsommingsteken wordt.
const ruw = payload.aanvullingen && typeof payload.aanvullingen === 'object'
  ? payload.aanvullingen
  : {};
const aanvullingen = {};
for (const [kop, waarde] of Object.entries(ruw)) {
  const regels = (Array.isArray(waarde) ? waarde : String(waarde).split('\n'))
    .map((r) => String(r).trim())
    .filter(Boolean)
    .slice(0, 20);
  if (regels.length) aanvullingen[String(kop)] = regels;
}
if (!Object.keys(aanvullingen).length) {
  return mislukt('Geen aanvullingen meegestuurd.');
}

// Koppen matchen op de exacte tekst uit het verslag; de webapp stuurt terug wat
// ze getoond heeft. Een kop die niet voorkomt is een fout aan onze kant en
// verdient een melding, geen stilzwijgend genegeerde aanvulling.
const bestaandeKoppen = new Set(
  verslag.onderwerpen
    .filter((o) => o && typeof o === 'object')
    .map((o) => String(o.kop || ''))
);
const onbekend = Object.keys(aanvullingen).filter((k) => !bestaandeKoppen.has(k));
if (onbekend.length) {
  return mislukt(`Onbekende kop(pen) in dit verslag: ${onbekend.join(', ')}.`);
}

let bijgewerkt = 0;
const onderwerpen = verslag.onderwerpen.map((o) => {
  if (!o || typeof o !== 'object') return o;
  const regels = aanvullingen[String(o.kop || '')];
  if (!regels) return o;
  bijgewerkt += 1;
  return {
    ...o,
    // Bestaande aanvullingen worden vervangen, niet aangevuld: de webapp toont
    // wat er staat en stuurt het geheel terug, dus dit is idempotent en de
    // gebruiker kan een eerdere aanvulling ook weer corrigeren.
    aangevuld: regels,
    niet_besproken: false,
    // 'Kwam ter sprake, geen uitkomst vastgelegd' klopt niet meer zodra de
    // behandelaar de uitkomst zelf heeft opgeschreven.
    ter_sprake: null,
  };
});

const nieuwVerslag = { ...verslag, onderwerpen };

const execId = String($execution.id || 'single').replace(/[^0-9A-Za-z_-]/g, '_').slice(0, 32);
const argsFile = `/tmp/n8n_args_aanvulling_${execId}_${Date.now()}.json`;
fs.writeFileSync(
  argsFile,
  JSON.stringify({
    verslag: nieuwVerslag,
    referentie: String(resultaat.referentie || job.referentie || 'onbekend'),
    transcript: String(resultaat.transcript || ''),
    metadata: {
      dossier: resultaat.dossier || job.dossier || '',
      datum: resultaat.datum || job.datum || '',
      duur_seconden: resultaat.duur_seconden || job.duur_seconden || 0,
    },
  }),
  'utf8'
);

return [{
  json: {
    jobId,
    jobPad,
    argsFile,
    verslag: nieuwVerslag,
    koppen_bijgewerkt: bijgewerkt,
  },
}];

// Schrijft het bijgewerkte verslag terug in het jobbestand en antwoordt de
// webapp. Het DOCX heeft dezelfde bestandsnaam als eerst (die is afgeleid van de
// referentie), dus de bestaande downloadlink blijft kloppen — maar we sturen hem
// voor de zekerheid mee terug.
const fs = require('fs');

const voorbereid = $('Prepare Aanvulling').first()?.json || {};
if (voorbereid.success === false) {
  return [{ json: voorbereid }];
}

const cmd = $json || {};
const stdout = String(cmd.stdout || '');
const stderr = String(cmd.stderr || '');
const match = stdout.match(/SUCCESS:\s*(.+)/);
const filePath = match ? match[1].trim() : '';
const filename = filePath ? filePath.split('/').pop() : '';

if (!filePath) {
  return [{
    json: {
      success: false,
      error:
        `Verslag-DOCX niet opnieuw gegenereerd. stdout=${stdout.slice(0, 200)}; ` +
        `stderr=${stderr.slice(0, 200)}`,
    },
  }];
}

let job = {};
try {
  job = JSON.parse(fs.readFileSync(voorbereid.jobPad, 'utf8'));
} catch (_) {
  // Jobbestand intussen opgeruimd: het DOCX staat er wel, dus dat melden we
  // gewoon. Alleen de volgende poll van de webapp vindt dan niets meer.
}

const resultaat = {
  ...(job.resultaat || {}),
  verslag: voorbereid.verslag,
  filename,
  file_path: filePath,
  download_url: `/output/${filename}`,
  aangevuld_op: new Date().toISOString(),
};

try {
  fs.writeFileSync(
    voorbereid.jobPad,
    JSON.stringify({ ...job, resultaat, bijgewerkt_op: new Date().toISOString() }),
    'utf8'
  );
} catch (_) {
  // Zie boven: niet kunnen bijwerken maakt het verslag niet ongeldig.
}

return [{
  json: {
    success: true,
    job_id: voorbereid.jobId,
    koppen_bijgewerkt: voorbereid.koppen_bijgewerkt,
    filename,
    download_url: resultaat.download_url,
    verslag: voorbereid.verslag,
  },
}];
